import novamind_api as nm
r = nm.query("SELECT category, COUNT(*) as n, SUM(amount) as amt FROM ledger WHERE day>=155 GROUP BY category ORDER BY amt")
for row in r['rows']: print(f"{row['category']:28} n={row['n']:6} ${row['amt']:,.0f}")

